export async function collectHistoricalLogs<T>(
  query: (fromBlock: number, toBlock: number) => Promise<T[]>,
  fromBlock: number,
  toBlock: number,
  onRecovery: (action: RecoveryAction) => void = () => {},
  callBudget = 64,
): Promise<T[]> {
  if (
    !Number.isSafeInteger(fromBlock) ||
    !Number.isSafeInteger(toBlock) ||
    fromBlock < 0 ||
    toBlock < fromBlock ||
    !Number.isSafeInteger(callBudget) ||
    callBudget < 1
  )
    throw new Error("Invalid historical query bounds");
  let calls = 0;
  const attempt = async (from: number, to: number): Promise<T[]> => {
    const read = async () => {
      if (++calls > callBudget)
        throw new Error(
          "Historical query call budget exhausted; review required",
        );
      return neatlogs.traceSpan(
        "historicalLogQuery",
        "TOOL",
        { fromBlock: from, toBlock: to, attempt: calls },
        () => query(from, to),
      );
    };
    try {
      return await rpcRead(read, {
        shouldRetry: (error) => !rangeLimited(error) && calls < callBudget,
        onRetry: () =>
          onRecovery({
            action: "RETRY_RPC",
            fromBlock: from,
            toBlock: to,
            reason:
              "Transient or unknown RPC failure; retrying the same bounded range",
          }),
      });
    } catch (error) {
      if (!rangeLimited(error) || from === to || calls >= callBudget)
        throw error;
      const midpoint = Math.floor((from + to) / 2);
      onRecovery({
        action: "SPLIT_LOG_RANGE",
        fromBlock: from,
        toBlock: to,
        reason:
          "Provider rejected range size; partition into disjoint inclusive ranges",
      });
      // Sequential queries keep provider pressure bounded and preserve chain order.
      return [
        ...(await attempt(from, midpoint)),
        ...(await attempt(midpoint + 1, to)),
      ];
    }
  };
  return attempt(fromBlock, toBlock);
}

public async traceSpan<T>(
  name: string,
  kind: Kind,
  attributes: Record<string, unknown>,
  fn: () => Promise<T>,
): Promise<T> {
  const context = this.context.getStore();
  if (!context) return this.runWorkflow(name, attributes, fn);
  const started = performance.now();
  const spanId = randomUUID();
  let status: "OK" | "ERROR" = "OK";
  let error: string | undefined;
  try {
    return await trace(
      { name, kind, input: attributes, attributes },
      async (sdkSpan) => {
        if (kind === "WORKFLOW")
          context.record.traceId = sdkSpan.spanContext().traceId;
        return this.context.run(
          { record: context.record, parentSpanId: spanId },
          async () => {
            const result = await fn();
            setTraceOutput(summary(result));
            return result;
          },
        );
      },
    );
  } catch (e) {
    status = "ERROR";
    error = e instanceof Error ? e.message : String(e);
    throw e;
  } finally {
    context.record.spans.push({
      spanId,
      parentSpanId: context.parentSpanId,
      name,
      kind,
      durationMs: performance.now() - started,
      attributes,
      status,
      error,
    });
  }
}

const query = <T>(
  fn: (from: number, to: number) => Promise<T[]>,
  from: number,
  to: number,
) =>
  collectHistoricalLogs(fn, from, to, (action) => {
    if (action.action === "RETRY_RPC") onRetry();
    onRecovery?.(action);
  });
